import{_ as r,o as t,c as a,aA as p}from"./chunks/framework.BMzE2Z9R.js";const u=JSON.parse('{"title":"关于资料和Q群","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"other/documents_and_qq_group.md","filePath":"other/documents_and_qq_group.md","lastUpdated":1778399398000}'),o={name:"other/documents_and_qq_group.md"};function n(i,e,l,s,h,c){return t(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="关于资料和q群" tabindex="-1">关于资料和Q群 <a class="header-anchor" href="#关于资料和q群" aria-label="Permalink to &quot;关于资料和Q群&quot;">​</a></h1><p>&#39;&#39;&#39;这边说一下 知道的和通用人工智能关系比较大的资源资料&#39;&#39;&#39;</p><p>嗯 我（jc）现在的认识，</p><p>通用人工智能（Artificial General Intelligence，AGI）算是传统的强人工智能，包含强人工智能，但是定义更严谨合理，。</p><p>OpenNARS是众多通用人工智能项目之一，是我们这边比较熟悉的</p><p>如果一定要给NARS从数学上找一个依托，是魔改了的贝叶斯网络。</p><p>但是出发点不同，哲学不同，哲学不同&gt;建模不同&gt;程序不同。然后就完全不同。NARS有一套自己的科学哲学体系，虽然也继承很多。</p><p>王老师在这个领域深入思考很多年，很多问题都是想过的。</p><hr><p>＃0基础入门引入式视频：<a href="http://www.dushuren123.com/dushuren/video/share.html?id=1679351024" target="_blank" rel="noreferrer">http://www.dushuren123.com/dushuren/video/share.html?id=1679351024</a></p><p>＃GitHub-<a href="http://www.opennars.org/" target="_blank" rel="noreferrer">OpenNARS</a></p><p>＃Github-<a href="https://wiki.opencog.org/w/The_Open_Cognition_Project" target="_blank" rel="noreferrer">OpenCog</a></p><p>＃X-其他AGI项目 <a href="https://www.jiqizhixin.com/articles/2018-11-15-6" target="_blank" rel="noreferrer">https://www.jiqizhixin.com/articles/2018-11-15-6</a></p><p>＃网站-通用人工智能协会群（主要是NARS的<strong>367446800</strong>）</p><p>＃Q群-通用人工智能贴吧群<strong>528053635</strong></p><p>＃视频和会议资料-b站：刘凯_AGI 给一个<a href="https://www.bilibili.com/video/BV1zA411u7rC%E3%80%82%E4%BC%9A%E8%AE%AE%E8%AE%B0%E5%BD%95%E9%87%8C%E8%83%BD%E7%9C%8B%E5%88%B0%E5%A4%A7%E9%87%8F%E5%85%B6%E4%BB%96%E5%AD%A6%E8%80%85%E7%9A%84%E8%BA%AB%E5%BD%B1" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1zA411u7rC。会议记录里能看到大量其他学者的身影</a></p><p>＃X-王培的著作和Google Scholar页面<a href="https://scholar.google.com/citations?hl=en&amp;user=-EYJLoMAAAAJ" target="_blank" rel="noreferrer">https://scholar.google.com/citations?hl=en&amp;user=-EYJLoMAAAAJ</a> 虽然引用量是不是很好，AGI本来就是小圈子就是</p><p>＃X-大量文件资料-通用人工智能协会群群文件。包括12年到20年的AGI国际会议会议记录，关于NARS的几本书《NAL》《Rigid Flexibility》，以及等等等等。</p><p>＃NARS的理论资料的讲解<a href="https://cis.temple.edu/~pwang/papers.html" target="_blank" rel="noreferrer">https://cis.temple.edu/~pwang/papers.html</a></p><p>＃博客-研究者破尔狼的博客<a href="https://moketao.gitee.io/2019/10/11/agi-and-ai/" target="_blank" rel="noreferrer">https://moketao.gitee.io/2019/10/11/agi-and-ai/</a></p><p>＃公众号-赛先生</p><p>＃公众号-反朴</p><p>＃公众号-混沌巡洋舰</p><p>＃公众号-真正的人工智能</p><p>＃X-北大朱松纯 暗物智能理论。我不了解，这里有一个这边给的解读 <a href="https://www.bilibili.com/video/BV1wf4y1k7Yh?p=21" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1wf4y1k7Yh?p=21</a></p><p>＃视频-YouTube-用户SingularityNET <a href="https://www.youtube.com/channel/UCbTE8vfz5zuEK5uRnc2yjrw" target="_blank" rel="noreferrer">https://www.youtube.com/channel/UCbTE8vfz5zuEK5uRnc2yjrw</a></p><p>＃视频-YouTube搜索OpenNARS。能搜索到一些</p>',27)])])}const d=r(o,[["render",n]]);export{u as __pageData,d as default};
